CREATE TYPE ticket_status AS ENUM ('open','claimed','waiting_member','waiting_staff','escalated','closed');
CREATE TYPE order_status AS ENUM ('pending','awaiting_payment','paid','fulfilling','fulfilled','cancelled','refunded');

CREATE TABLE native_settings (guild_id text NOT NULL, system text NOT NULL, config jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(guild_id,system));
CREATE TABLE native_idempotency (scope text NOT NULL, idempotency_key text NOT NULL, input_hash text NOT NULL, status text NOT NULL, result jsonb, error jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope,idempotency_key));

CREATE TABLE tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, sequence bigint GENERATED BY DEFAULT AS IDENTITY, member_id text NOT NULL, category_key text NOT NULL, channel_id text, status ticket_status NOT NULL DEFAULT 'open', priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), assignee_id text, tags text[] NOT NULL DEFAULT '{}', subject text NOT NULL, opened_at timestamptz NOT NULL DEFAULT now(), first_response_at timestamptz, due_at timestamptz, closed_at timestamptz, reopened_at timestamptz, escalation_level integer NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX tickets_channel_unique ON tickets(channel_id) WHERE channel_id IS NOT NULL;
CREATE INDEX tickets_member_open_idx ON tickets(guild_id,member_id,status);
CREATE INDEX tickets_sla_idx ON tickets(status,due_at) WHERE due_at IS NOT NULL;
CREATE TABLE ticket_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets ON DELETE CASCADE, actor_id text, kind text NOT NULL, visibility text NOT NULL DEFAULT 'staff' CHECK(visibility IN ('staff','member','system')), body text, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_transcripts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets ON DELETE CASCADE, sha256 text NOT NULL, format text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_satisfaction (ticket_id uuid PRIMARY KEY REFERENCES tickets ON DELETE CASCADE, member_id text NOT NULL, score integer NOT NULL CHECK(score BETWEEN 1 AND 5), comment text, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE verification_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, member_id text NOT NULL, status text NOT NULL CHECK(status IN ('pending_rules','challenge','manual_review','quarantined','verified','expired','denied')), challenge_hash text, attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, risk_score integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, rules_accepted_at timestamptz, verified_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX verification_active_unique ON verification_sessions(guild_id,member_id) WHERE status IN ('pending_rules','challenge','manual_review','quarantined');
CREATE INDEX verification_expiry_idx ON verification_sessions(status,expires_at);

CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, sku text NOT NULL, name text NOT NULL, description text, acceptable_use text NOT NULL, active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,sku));
CREATE TABLE product_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products ON DELETE CASCADE, sku text NOT NULL UNIQUE, name text NOT NULL, price_minor bigint NOT NULL CHECK(price_minor>=0), currency char(3) NOT NULL, stock integer CHECK(stock IS NULL OR stock>=0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0), delivery_config jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(stock IS NULL OR reserved<=stock));
CREATE TABLE carts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, member_id text NOT NULL, status text NOT NULL DEFAULT 'active', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX carts_active_unique ON carts(guild_id,member_id) WHERE status='active';
CREATE TABLE cart_items (cart_id uuid NOT NULL REFERENCES carts ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES product_variants, quantity integer NOT NULL CHECK(quantity>0), PRIMARY KEY(cart_id,variant_id));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, member_id text NOT NULL, cart_id uuid REFERENCES carts, status order_status NOT NULL DEFAULT 'pending', currency char(3) NOT NULL, subtotal_minor bigint NOT NULL CHECK(subtotal_minor>=0), refund_minor bigint NOT NULL DEFAULT 0 CHECK(refund_minor>=0), risk_flags jsonb NOT NULL DEFAULT '[]', provider text, provider_reference text, acceptable_use_accepted_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_reference));
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES product_variants, sku text NOT NULL, name text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), unit_price_minor bigint NOT NULL CHECK(unit_price_minor>=0));
CREATE TABLE payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, event_id text NOT NULL, signature_hash text NOT NULL, event_type text NOT NULL, order_id uuid REFERENCES orders, payload_hash text NOT NULL, processed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,event_id));
CREATE TABLE fulfillment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders ON DELETE CASCADE, state text NOT NULL, mechanism text NOT NULL, receipt jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commerce_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders, member_id text NOT NULL, score integer NOT NULL CHECK(score BETWEEN 1 AND 5), body text, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,member_id));

CREATE TABLE moderation_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, sequence bigint GENERATED BY DEFAULT AS IDENTITY, member_id text NOT NULL, opened_by text NOT NULL, status text NOT NULL DEFAULT 'open', severity integer NOT NULL CHECK(severity BETWEEN 1 AND 5), reason_code text NOT NULL, summary text NOT NULL, action text, action_expires_at timestamptz, appeal_ticket_id uuid REFERENCES tickets, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX moderation_expiry_idx ON moderation_cases(status,action_expires_at);
CREATE TABLE moderation_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES moderation_cases ON DELETE CASCADE, added_by text NOT NULL, kind text NOT NULL, uri text, sha256 text, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES moderation_cases ON DELETE CASCADE, author_id text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES moderation_cases, action text NOT NULL, discord_receipt jsonb NOT NULL, verified boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE marketing_consent (guild_id text NOT NULL, member_id text NOT NULL, purpose text NOT NULL, status text NOT NULL CHECK(status IN ('opted_in','opted_out')), source text NOT NULL, proof jsonb NOT NULL DEFAULT '{}', consented_at timestamptz, opted_out_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(guild_id,member_id,purpose));
CREATE TABLE marketing_segments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, name text NOT NULL, purpose text NOT NULL, criteria jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, name text NOT NULL, purpose text NOT NULL, status text NOT NULL CHECK(status IN ('draft','scheduled','sending','completed','cancelled')), template jsonb NOT NULL, segment_id uuid NOT NULL REFERENCES marketing_segments, scheduled_at timestamptz, quiet_hours jsonb NOT NULL DEFAULT '{}', rate_per_minute integer NOT NULL DEFAULT 20 CHECK(rate_per_minute BETWEEN 1 AND 100), experiment jsonb NOT NULL DEFAULT '{}', created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns ON DELETE CASCADE, member_id text NOT NULL, status text NOT NULL, variant text, attribution_token text UNIQUE NOT NULL, sent_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}', UNIQUE(campaign_id,member_id));

CREATE TABLE analytics_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id text NOT NULL, event_name text NOT NULL, subject_type text, subject_id text, occurred_at timestamptz NOT NULL DEFAULT now(), dimensions jsonb NOT NULL DEFAULT '{}', metrics jsonb NOT NULL DEFAULT '{}', privacy_class text NOT NULL DEFAULT 'aggregate', idempotency_key text UNIQUE NOT NULL);
CREATE INDEX analytics_rollup_idx ON analytics_events(guild_id,event_name,occurred_at);
CREATE TABLE analytics_daily (guild_id text NOT NULL, day date NOT NULL, event_name text NOT NULL, dimensions_hash text NOT NULL, dimensions jsonb NOT NULL DEFAULT '{}', count bigint NOT NULL DEFAULT 0, sums jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(guild_id,day,event_name,dimensions_hash));
